"""Audit completed mixture runs, retaining failures instead of certifying them."""
import argparse
import json
import numpy as np
from scipy.special import logsumexp
import source_evidence as se
import dynesty
from dynesty.utils import resample_run


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("run_name")
    parser.add_argument("--bootstrap", type=int, default=64)
    args = parser.parse_args()
    folder = se.ROOT/"runs"/args.run_name
    report = json.loads((folder/"RESULT.json").read_bytes())
    if report["registration_sha256"] != se.sha(se.REG):
        raise ValueError("Run registration changed")
    if report["arrays_sha256"] != se.sha(folder/"samples.npz"):
        raise ValueError("Run samples changed")
    # Checkpoint is generated by this local registered runner, not an external pickle.
    # __main__ bindings are required for checkpoints created by script execution.
    import __main__
    __main__.loglike = se.loglike
    __main__.prior_transform = se.prior_transform
    sampler = dynesty.NestedSampler.restore(str(folder/"checkpoint.pkl"))
    result = sampler.results
    with np.load(folder/"samples.npz") as data:
        samples = data["samples"].copy()
        original_logl = data["logl"].copy()
        components = data["components"].copy()
        measured = data["lnB"].copy()
    if not np.array_equal(samples, result.samples) or not np.array_equal(original_logl, result.logl):
        raise ValueError("Final checkpoint differs from saved samples")
    if not np.array_equal(components, np.stack(result.blob)):
        raise ValueError("Checkpoint component likelihoods differ")
    count = components.shape[1]//2
    repeat = []
    for k in range(args.bootstrap):
        boot = resample_run(result, rstate=np.random.default_rng(130600+k))
        blobs = np.stack(boot.blob)
        # Compute evidence integrals alone, avoiding repeated ESS work.
        integrals = logsumexp(boot.logwt[:, None]+blobs-boot.logl[:, None], axis=0)
        repeat.append(integrals[count:]-integrals[:count])
    mc = np.std(repeat, axis=0, ddof=1)
    state = se.load_state()
    z, ess, maximum = se.component_integrals(result.logwt, result.logl, components)
    within_weights = (np.minimum(ess[:count], ess[count:]) >= 100)&(np.maximum(maximum[:count], maximum[count:]) <= .05)
    within_precision = mc <= .2
    # Rate control at samples carrying substantial posterior weight in diverse
    # components, not at arbitrary prior points irrelevant to the integral.
    logweights = result.logwt[:, None]+components-result.logl[:, None]-z[None, :]
    selected = set()
    for cell in report["rows"]:
        idx = next(i for i, label in enumerate(state["labels"])
                   if all(label[k] == v for k, v in cell["cell"].items()))
        for component in (idx, idx+count):
            selected.add(int(np.argmax(logweights[:, component])))
    rate_checks = []
    for i in sorted(selected):
        new = se.component_loglikes(report["family"], samples[i], state, sample_rate=16384)
        delta = new-components[i]
        active = np.exp(logweights[i]) >= .01
        maximum_change = float(np.max(np.abs(delta[active]))) if active.any() else 0.
        rate_checks.append(dict(sample_index=i, components_with_weight_above_one_percent=int(active.sum()),
                                max_logL_change_these_components=maximum_change,
                                max_logL_change_all_components=float(np.max(np.abs(delta)))))
    rate_ok = all(r["max_logL_change_these_components"] <= .1 for r in rate_checks)
    se.save_arrays(folder/"AUDIT_ARRAYS.npz", bootstrap_lnB=np.array(repeat), MC_sd_lnB=mc,
                   weight_pass=within_weights, precision_pass=within_precision)
    rows = []
    for r in report["rows"]:
        ii = np.array([i for i, label in enumerate(state["labels"])
                       if all(label[k] == v for k, v in r["cell"].items())])
        rows.append(dict(cell=r["cell"], min_ESS=r["min_ESS"], max_single_weight=r["max_single_weight"],
                         lnB_mean=r["lnB_mean"], lnB_sd_noise=r["lnB_sd"],
                         median_MC_sd=float(np.median(mc[ii])), max_MC_sd=float(mc[ii].max()),
                         draws_passing_weight_precision=int(np.count_nonzero(within_weights[ii]&within_precision[ii])), N=len(ii),
                         status="NEEDS_INDEPENDENT_REPEAT" if np.all(within_weights[ii]&within_precision[ii]) and rate_ok and not report["maxcall_reached"]
                                else "INTEGRATION_PRECISION_INSUFFICIENT"))
    outcome = dict(status="PILOT_AUDITED_NOT_ACCEPTED", rows=rows, bootstrap_runs=args.bootstrap,
                   all_weights_pass=bool(within_weights.all()), all_MC_precision_pass=bool(within_precision.all()),
                   sample_rate_checks=rate_checks, sample_rate_pass=rate_ok, repeat_convergence=False,
                   maxcall_reached=report["maxcall_reached"], source_dimensions=7, physical_confirmation=False,
                   scope="Bootstrap and rate checks do not detect all missing modes; independent larger-live-point run is still mandatory",
                   hashes={name:se.sha(folder/name) for name in ("RESULT.json", "samples.npz", "checkpoint.pkl", "AUDIT_ARRAYS.npz")},
                   source_sha256=se.sha(se.ROOT/se.Path(__file__).name))
    se.write(folder/"AUDIT.json", outcome)
    print(json.dumps({k:outcome[k] for k in ("status", "all_weights_pass", "all_MC_precision_pass", "sample_rate_pass", "maxcall_reached")}), flush=True)


if __name__ == "__main__":
    main()
